#!/bin/bash
# STAGE 1b -- can sigma be reduced by training to convergence? The pre-registered follow-on.
#
# DO NOT EDIT THIS FILE WHILE IT RUNS. Bash reads a script by byte offset; the last edit of a
# running script here changed its length, the shell resumed mid-token and died after 34 hours of
# completed training. Any fix waits for the run to end.
#
# WHY. Stage 1 measured the settled recipe's holdout sigma at 4.42 over six seeds, spanning 11.6
# points, which makes the holdout untestable at any affordable n (35 seeds a side for delta=3).
# The only contrasting datum is the old four-seed floor: sigma 1.07 on the same metric, from a
# recipe trained to TWO epochs. Seeds enter the required count SQUARED, so halving sigma is worth
# more than quadrupling seeds and costs far less. This tests convergence as the driver.
#
# DESIGN. Both recipes, six matched seeds, two epochs, identical in every other respect to
# Stage 1. Scoring BOTH checkpoints separates two things a single comparison would confound:
#   epoch2 vs epoch1-of-this-run  = convergence
#   epoch1-of-this-run vs Stage 1 = the LR schedule alone (a 2-epoch cosine differs at epoch 1)
#
# PREDICTION, recorded before the GPU starts:
#   sigma(holdout, epoch2) falls MATERIALLY below 4.42, to roughly 2 or under. If it reaches 2.0
#   the seeds needed for delta=3 drop from 35 a side to 7, and a factorial becomes affordable.
#   The vocabulary effect should replicate at about +71 on eval_vocab, far outside any sigma.
#   REFUTED IF: sigma(holdout, epoch2) >= 3.5. Then convergence is not the driver, this recipe is
#   intrinsically seed-unstable at 0.8B, and the holdout should be RETIRED as a comparative
#   instrument rather than fixed -- reported descriptively, with eval_vocab and eval_t5 (sigma
#   1.69 and 1.78) carrying every comparison.
#
# BUDGET. 12 trainings at ~6.8 h = ~82 h, plus 120 scoring runs at ~2 min = ~4 h. About 3.6 days
# of the week, leaving slack for a failure and for whatever the result argues for next.
set -u
export PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True
cd /srv/logical/workspace/home/teague/Projects/astcss-eval/trees/tune/setup
L=workspace/logs/stage1b; mkdir -p "$L"; PY=~/.venvs/astcss-tune/bin/python
B08=/home/teague/.cache/huggingface/hub/models--Qwen--Qwen3.5-0.8B/snapshots/2fc06364715b967f1860aea9cf38778875588b17
note(){ echo "$(date +%F' '%H:%M:%S) [1b] $*" | tee -a "$L/queue.log"; }
trap 'workspace/ocr_pause.sh resume >/dev/null 2>&1' EXIT
workspace/ocr_pause.sh hold $$ || note "WARNING: OCR not paused -- scoring will be ~3.5x slower"
note "start: 2 recipes x 6 seeds x 2 epochs"

for spec in "base:t5-langcard" "pairs:t5-v1full"; do
  rec=${spec%%:*}; data=${spec##*:}
  for s in 18 19 20 21 22 23; do
    out=workspace/adapters/s1b-$rec-seed$s
    if [ -d "$out/epoch2" ]; then note "$(printf '%-6s seed %-3s' $rec $s) cached"; continue; fi
    t0=$SECONDS
    $PY tune/train_qlora.py --base "$B08" --quant none --data workspace/datasets/$data \
      --out "$out" --epochs 2 --accum 16 --lr 2e-4 --seed $s --max-len 1024 \
      > "$L/train-$rec-$s.log" 2>&1
    if [ ! -d "$out/epoch2" ]; then note "$(printf '%-6s seed %-3s' $rec $s) TRAIN FAILED: $(tail -2 $L/train-$rec-$s.log | tr '\n' ' ' | cut -c1-100)"; continue; fi
    note "$(printf '%-6s seed %-3s' $rec $s) trained in $(( (SECONDS-t0)/60 ))m $(grep -oE 'val loss [0-9.]+' "$L/train-$rec-$s.log" | tr '\n' ' ')"
  done
done
note "training done; scoring 12 adapters x 2 epochs x 5 suites"

for spec in "base" "pairs"; do
  for s in 18 19 20 21 22 23; do
    for ep in epoch1 epoch2; do
      ad=workspace/adapters/s1b-$spec-seed$s/$ep
      [ -d "$ad" ] || continue
      for d in holdout holdout_rw holdout_noise eval_vocab eval_t5; do
        out=runs/s1b-$spec-s$s-$ep-$d
        [ -s "$out/scores.jsonl" ] && continue
        $PY tune/local_generate.py --base "$B08" --name "local:s1b-$spec-s$s-$ep" --batch 8 \
          --quant none --out "$out" --card card_pd.md --pairs-dir $d --adapter "$ad" \
          > "$L/gen-$spec-$s-$ep-$d.log" 2>&1
        [ -s "$out/responses.jsonl" ] || { note "$spec s$s $ep $d GEN FAILED"; continue; }
        env -u SITTING_DUCK -u ASTCSS_MACROS ASTCSS_EXEC_JOBS=8 \
          python3 qualify.py score --out "$out" --pairs-dir $d > "$L/score-$spec-$s-$ep-$d.log" 2>&1
      done
      note "$(printf '%-6s seed %-3s %s scored' $spec $s $ep)"
    done
  done
done
note "done"
